@page "/settings"
@rendermode InteractiveServer
@inject sv_6829438e582a4bbdbe27cee63425f4a2.Services.ThemeService ThemeService
@implements IDisposable

<PageTitle>Settings</PageTitle>

<h3>User Preferences</h3>

<div class="card p-4" style="max-width: 500px; border-color: @ThemeService.AccentColor;">
    <div class="mb-3">
        <label class="form-label fw-bold">Theme</label>
        <select class="form-select" @bind="SelectedTheme">
            <option value="Light">Light</option>
            <option value="Dark">Dark</option>
            <option value="System">System</option>
        </select>
    </div>

    <div class="mb-3">
        <label class="form-label fw-bold">Accent Color</label>
        <input type="color" class="form-control form-control-color"
               value="@ThemeService.AccentColor"
               @onchange="OnAccentColorChanged" />
        <small class="text-muted">@ThemeService.AccentColor</small>
    </div>

    <div class="alert alert-info">
        Current: <strong>@ThemeService.Theme</strong> with accent
        <span style="color: @ThemeService.AccentColor;">■</span>
        @ThemeService.AccentColor
    </div>
</div>

@code {
    private string SelectedTheme
    {
        get => ThemeService.Theme.ToString();
        set
        {
            if (Enum.TryParse<sv_6829438e582a4bbdbe27cee63425f4a2.Services.ThemeMode>(value, out var mode))
            {
                ThemeService.Theme = mode;
            }
        }
    }

    protected override void OnInitialized()
    {
        ThemeService.OnChange += StateHasChanged;
    }

    private void OnAccentColorChanged(ChangeEventArgs e)
    {
        ThemeService.AccentColor = e.Value?.ToString() ?? "#0d6efd";
    }

    public void Dispose()
    {
        ThemeService.OnChange -= StateHasChanged;
    }
}

